def is_costas(x):
    n=len(x)
    if sorted(x)!=list(range(n)): return False
    seen=set()
    for c1 in range(n):
        for c2 in range(c1+1,n):
            v=(c2-c1,x[c2]-x[c1])
            if v in seen:
                print('dup',v,c1,c2)
                return False
            seen.add(v)
    return True
